target.echo:
@echo off
            echo ========================================
            echo Starting Clinic System...
            echo ========================================
            echo.

            REM Check if Java is installed
            java -version >nul 2>1
            if %ERRORLEVEL% NEQ 0 (
            echo ERROR: Java is not installed!
            echo.
            echo Please install Java 8 or higher from:
            echo https://www.java.com/download
            echo.
            pause
            exit /b 1
            )

            REM Run the application
            java -jar ClinicSystem.jar

            REM Check if application crashed
            if %ERRORLEVEL% NEQ 0 (
            echo.
            echo ========================================
            echo Application closed with errors
            echo ========================================
            pause
            )
